1	import { hitsOn } from "./hits.ts";
2	import { subjectTitle } from "./eligibility.ts";
3	import { modeDoc, summaryDoc, type Doc, type Pack, type Phase } from "@runlog/rules-schema";
4	import { activePhases, constrainedByOf, constraintsFor, nextStep, phaseSkipped } from "./flow.ts";
5	import { clockOfUnit, elapsedMs, liveClocks, unitClockFor } from "./clock.ts";
6	import { describeSkipReason } from "./describe.ts";
7	import { availableMoves } from "./execute.ts";
8	import { mayQuote } from "./export.ts";
9	import { progressOf } from "./race.ts";
10	import { formatScore, scoreOf } from "./score.ts";
11	import { standings } from "./moderated.ts";
12	import { subjectName } from "./eligibility.ts";
13	import type { RunEvent } from "./events.ts";
14	import type { RunState } from "./types.ts";
15	
16	/**
17	 * A run as anyone may see it: the state and the log, worded, with the
18	 * pack's own text only where its license lets the text travel.
19	 *
20	 * This is what a stranger with a live link gets, what a stream widget
21	 * draws, and what the owner's device writes to the server after each
22	 * move for a run whose pack may not be handed over. The engine's state is
23	 * not shipped as such: it names table entries and states by id, which
24	 * are meaningless without the pack, and a pack marked not for
25	 * redistribution must not follow. So the snapshot carries labels and
26	 * numbers, and for the log the words of the one entry each roll landed
27	 * on: that much is the run, not the pack. The pack's paper and its tables
28	 * whole travel only where they may be quoted.
29	 *
30	 * Lives in the engine, not the app, so a server that never renders
31	 * anything, the Discord bot's Lambda, say, can write the same snapshot
32	 * the owner's browser would, from the same event log, with no DOM in
33	 * reach anywhere in the call.
34	 */
35	/**
36	 * One thing a phase produced: the text, and, where it came from a table
37	 * the phase set off rather than one its own step rolls, which table and
38	 * which piece it hit, so a page can color it the way the log colors a
39	 * hit. The piece is named as well as numbered: "hit #3" makes a reader
40	 * go and look up which piece that was, on a page that may not be in front
41	 * of them. The number stays for a page written before the name was
42	 * carried, and for one built before it was. The declared type carries its
43	 * mark too. Plain text is what an older snapshot carries, and still reads.
44	 */
45	export type PhaseResult = string | { text: string; table?: string; hit?: number | null; hitName?: string; declared?: true };
46	
47	/** A result's words, whichever shape it came in. */
48	export function resultText(r: PhaseResult): string {
49	  return typeof r === "string" ? r : r.text;
50	}
51	
52	export interface LiveSnapshot {
53	  v: 1;
54	  at: string;
55	  packId: string;
56	  packTitle: string;
57	  runName: string | null;
58	  mode: string;
59	  /** The mode's id, for the paper about it; absent from snapshots written before it was carried. */
60	  modeId?: string;
61	  words: { run: string; unit: string; units: string };
62	  status: "active" | "ended";
63	  ending: string | null;
64	  unit: number;
65	  /** Where the flow is: the phase and step the run is waiting on. */
66	  where: string | null;
67	  /** The step in hand, on its own, and the unit's phases with where each stands: what the player's own screen lists. */
68	  step: string | null;
69	  /** The current step's `kind`-`"manual"`, `"declareSubject"`, and so on; null with no step. Absent from snapshots written before it was carried. */
70	  stepKind?: string | null;
71	  /**
72	   * What the outside may ask this run for at this moment: whether a table
73	   * is waiting to be rolled, and the moves on offer by id and label.
74	   *
75	   * Offered, not declared. Whether a move is available depends on the
76	   * pack's conditions and on what has already been spent, so
77	   * only a device holding the pack and the log can say; the server has
78	   * neither and answers a chat bot from this. Absent from snapshots
79	   * written before it was carried.
80	   */
81	  asks?: { roll: boolean; moves: Array<{ id: string; label: string }> };
82	  phases: Array<{
83	    id: string;
84	    label: string;
85	    state: "done" | "current" | "skipped" | "todo";
86	    why?: string;
87	    /** What the phase produced this unit, in order: the results of the tables its steps roll, and the subject's declared type where it declares one. Absent when nothing yet. A snapshot written before results said where they came from carries them as plain text. */
88	    results?: PhaseResult[];
89	  }>;
90	  /** Every unit so far, as what each of its phases produced, oldest first; a phase that produced nothing in a unit is left out. Absent from snapshots written before it was carried. */
91	  units?: Array<{ unit: number; phases: Array<{ id: string; label: string; results: PhaseResult[] }> }>;
92	  /**
93	   * A rule drawn earlier this unit that the current step must honor, in the
94	   * pack's own words: the same lines the player's own screen shows in
95	   * front of them while they work. Empty off a step with nothing to honor,
96	   * or one with no `constrainedBy` table. Absent from snapshots written
97	   * before it was carried.
98	   */
99	  constraints?: string[];
100	  /** The pack's text may be handed over whole here: its paper, its tables. The log carries the drawn entries' words either way. */
101	  quoted: boolean;
102	  standings: Array<{ name: string; points: number; place: number; states: string[] }>;
103	  contestants: number;
104	  subjects: Array<{ id: number; name: string; type: string | null; states: string[]; finalized: boolean; hits?: string[] }>;
105	  counters: Array<{ id: string; label: string; value: number }>;
106	  resources: Array<{ id: string; label: string; value: number; max?: number; display?: "boxes" | "bar" | "number" }>;
107	  clocks: Array<{
108	    id: string;
109	    label: string;
110	    kind: "stopwatch" | "timer";
111	    seconds: number | null;
112	    status: "running" | "paused" | "done";
113	    elapsedMs: number;
114	    expired: boolean;
115	  }>;
116	  /** Units closed, and time on the run. `timed` says the run keeps time by unit clocks; without them, elapsed is wall time since the start, which means little for a run played across days. */
117	  progress: { unitsDone: number; elapsedMs: number; timed: boolean };
118	  /** What the pack (or its mode) says this run scores, worded and ready to show. */
119	  score: { label: string; text: string; value: number; better: "higher" | "lower" };
120	  forcedUnits: number;
121	  /** Newest first, numbered from the start. */
122	  log: Array<{ n: number; unit: number; where: string; hit: number | null; hitName?: string; text: string }>;
123	  /**
124	   * Every result rolled this unit, in the order the dice landed on them:
125	   * "this unit so far" for a watcher, and a table a manual step draws its
126	   * constraints from may be rolled more than once. Absent from snapshots
127	   * written before it was carried.
128	   */
129	  unitResults?: Array<{ table: string; text: string; hit: number | null; hitName?: string }>;
130	  /** The most recent log line, for a widget that shows one thing rather than the whole log. Null with nothing rolled yet; absent from snapshots written before it was carried. */
131	  latest?: { where: string; text: string } | null;
132	  /** The race this run is in, as its owner's device last saw the leaderboard; absent outside a race. */
133	  race?: RaceSnapshot;
134	  /**
135	   * The paper a watcher may read: the pack's summary and the mode's, as
136	   * the summary tells them, the shape of the game, never a rule, so a
137	   * link to a pack that may not travel still says what is being played.
138	   * Written by the owner's device with the snapshot; the server reads no pack.
139	   */
140	  paper?: Paper;
141	}
142	
143	export interface Paper {
144	  summary: Doc;
145	  mode: Doc | null;
146	}
147	
148	const papers = new WeakMap<Pack, Map<string, Paper>>();
149	
150	/** The summary and the mode's page, made once per pack and mode; the same object comes back after. */
151	export function paperOf(pack: Pack, modeId: string): Paper {
152	  let byMode = papers.get(pack);
153	  if (!byMode) {
154	    byMode = new Map();
155	    papers.set(pack, byMode);
156	  }
157	  let paper = byMode.get(modeId);
158	  if (!paper) {
159	    paper = { summary: summaryDoc(pack), mode: pack.modes[modeId] ? modeDoc(pack, modeId) : null };
160	    byMode.set(modeId, paper);
161	  }
162	  return paper;
163	}
164	
165	export interface RaceSnapshot {
166	  name: string | null;
167	  ended: boolean;
168	  racing: number;
169	  standings: Array<{ name: string; place: number; owner: boolean; line: string; elapsedMs: number }>;
170	}
171	
172	/**
173	 * The leaderboard as a snapshot carries it: names, places and a line
174	 * each in the pack's own words, so a viewer draws it without the pack.
175	 */
176	export function raceOf(
177	  race: { meta: { name?: string; endedAt?: string }; entries: readonly unknown[] } | null,
178	  standings: ReadonlyArray<{
179	    entry: {
180	      name?: string;
181	      progress?: { unit: number; unitsDone: number; status: "active" | "ended"; ending?: string; elapsedMs: number };
182	    };
183	    place: number;
184	    me: boolean;
185	  }>,
186	  words: { one: string; many: string },
187	): RaceSnapshot | undefined {
188	  if (!race) return undefined;
189	  return {
190	    name: race.meta.name ?? null,
191	    ended: Boolean(race.meta.endedAt),
192	    racing: race.entries.length,
193	    standings: standings.map(({ entry, place, me }) => {
194	      const p = entry.progress;
195	      const line = !p
196	        ? "not started"
197	        : p.status === "ended"
198	          ? `finished · ${p.unitsDone} ${p.unitsDone === 1 ? words.one.toLowerCase() : words.many.toLowerCase()}${p.ending ? ` · ${p.ending}` : ""}`
199	          : `${words.one} ${p.unit} · ${p.unitsDone} done`;
200	      return { name: entry.name ?? (me ? "You" : "Someone"), place, owner: me, line, elapsedMs: p?.elapsedMs ?? 0 };
201	    }),
202	  };
203	}
204	
205	const LOG_LINES = 60;
206	
207	/**
208	 * The line the dice landed on, in the pack's words, whatever the license
209	 * says about the pack: a watcher who sees "#mut-071" is watching numbers.
210	 * What the dice drew is one line of one table; the tables themselves and
211	 * the pack's paper stay behind `quoted`.
212	 */
213	export function entryTextOf(pack: Pack, o: Pick<RunState["outcomes"][number], "table" | "entryId">): string {
214	  const table = pack.tables[o.table];
215	  const entry = table?.entries.find((e) => e.id === o.entryId);
216	  return entry?.title ?? entry?.text ?? `${table?.title ?? o.table} · #${o.entryId}`;
217	}
218	
219	/**
220	 * A unit read as its phases: which one is in play, which are done, which
221	 * are out, and what each has produced so far.
222	 *
223	 * The watcher's page is built on this, and so is the list the app itself
224	 * opens over the step, so a player and somebody watching over their
225	 * shoulder are reading one thing rather than two things that drift.
226	 */
227	export function unitPhases(pack: Pack, state: RunState): LiveSnapshot["phases"] {
228	  return phasesOf(pack, state).phases;
229	}
230	
231	/** Everything snapshotOf and unitPhases both work out about a unit. */
232	function phasesOf(pack: Pack, state: RunState) {
233	  /** What a piece a result reached is called, for whoever reads that it did. */
234	  const named = (id: number | null | undefined): string | undefined => {
235	    if (id === null || id === undefined) return undefined;
236	    const subject = state.subjects.find((s) => s.id === id);
237	    return subject ? subjectTitle(pack, subject) : undefined;
238	  };
239	  const step = nextStep(pack, state);
240	  // Which phase each of a unit's results belongs under. A table one of a
241	  // phase's steps rolls is that phase's; a table no step rolls, one a
242	  // result triggered, a setback aimed at an earlier piece, belongs to the
243	  // phase whose roll led to it, which is the one before it in the log.
244	  const rolledBy = new Map<string, string>();
245	  for (const phase of activePhases(pack, state))
246	    for (const st of phase.steps) if (st.kind === "rollTable" && !rolledBy.has(st.table)) rolledBy.set(st.table, phase.id);
247	  const ownedIn = (unit: number): Array<{ outcome: RunState["outcomes"][number]; phase: string }> => {
248	    const owned: Array<{ outcome: RunState["outcomes"][number]; phase: string }> = [];
249	    let lastPhase: string | null = null;
250	    for (const o of state.outcomes) {
251	      if (o.unit !== unit) continue;
252	      const phaseId: string | null = rolledBy.get(o.table) ?? lastPhase;
253	      if (!phaseId) continue;
254	      owned.push({ outcome: o, phase: phaseId });
255	      lastPhase = phaseId;
256	    }
257	    return owned;
258	  };
259	  // What a phase produced in a unit, for the watcher's page: the results of
260	  // the tables its steps roll, in the order the dice landed, and the
261	  // declared type where a step declares. A result from the phase's own
262	  // table is its text; one from a table it set off says which table, and
263	  // which piece it hit, so the log need not be consulted to know what
264	  // happened and to what.
265	  const resultsOf = (phase: Phase, unit: number): PhaseResult[] => {
266	    const subject = state.subjects.find((s) => s.unit === unit && !s.removed);
267	    return [
268	      ...ownedIn(unit)
269	        .filter((x) => x.phase === phase.id)
270	        .map(({ outcome: o }): PhaseResult => {
271	          const own = rolledBy.get(o.table) === phase.id;
272	          const hit = o.targetSubject !== null && o.targetSubject !== undefined ? o.targetSubject : null;
273	          const text = entryTextOf(pack, o);
274	          const name = named(hit);
275	          return own && hit === null
276	            ? { text }
277	            : { text, table: pack.tables[o.table]?.title ?? o.table, hit, ...(name ? { hitName: name } : {}) };
278	        }),
279	      ...(phase.steps.some((st) => st.kind === "declareSubject") && subject?.type ? [{ text: subject.type, declared: true as const }] : []),
280	    ];
281	  };
282	  // Every unit so far, as what each of its phases produced: the whole run
283	  // told room by room, for a watcher who would rather read it that way
284	  // than as a log. A phase that produced nothing in a unit is left out.
285	  const units = Array.from({ length: state.unit }, (_, i) => i + 1).map((unit) => ({
286	    unit,
287	    phases: activePhases(pack, state)
288	      .map((phase) => ({ id: phase.id, label: phase.label, results: resultsOf(phase, unit) }))
289	      .filter((p) => p.results.length > 0),
290	  }));
291	  const phases =
292	    state.unit > 0 && state.status !== "ended"
293	      ? activePhases(pack, state).map((phase) => {
294	          const done = state.phasesDone.includes(phase.id);
295	          const current = step?.phase.id === phase.id;
296	          const skipped = !done && !current && phaseSkipped(pack, state, phase);
297	          const why = skipped ? describeSkipReason(pack, phase) : null;
298	          const results = resultsOf(phase, state.unit);
299	          return {
300	            id: phase.id,
301	            label: phase.label,
302	            state: done ? ("done" as const) : current ? ("current" as const) : skipped ? ("skipped" as const) : ("todo" as const),
303	            ...(why ? { why } : {}),
304	            ...(results.length > 0 ? { results } : {}),
305	          };
306	        })
307	      : [];
308	  return { step, phases, units };
309	}
310	
311	export function snapshotOf(
312	  pack: Pack,
313	  state: RunState,
314	  events: readonly RunEvent[],
315	  at: string = new Date().toISOString(),
316	  extra: { race?: RaceSnapshot | undefined } = {},
317	): LiveSnapshot {
318	  const v = pack.vocabulary;
319	  const quoted = mayQuote(pack, "share");
320	  const now = Date.parse(at);
321	  const { step, phases, units } = phasesOf(pack, state);
322	  const stepLabel = step
323	    ? "label" in step.step && step.step.label
324	      ? step.step.label
325	      : step.step.kind === "rollTable"
326	        ? (pack.tables[step.step.table]?.title ?? step.step.table)
327	        : step.phase.label
328	    : null;
329	  const stateLabel = (id: string) => pack.states?.[id]?.short ?? pack.states?.[id]?.label ?? id;
330	  /** What a piece a result reached is called, for whoever reads that it did. */
331	  const named = (id: number | null | undefined): string | undefined => {
332	    if (id === null || id === undefined) return undefined;
333	    const subject = state.subjects.find((s) => s.id === id);
334	    return subject ? subjectTitle(pack, subject) : undefined;
335	  };
336	  const total = state.outcomes.length;
337	  const log = [...state.outcomes]
338	    .reverse()
339	    .slice(0, LOG_LINES)
340	    .map((o, i) => ({
341	      n: total - i,
342	      unit: o.unit,
343	      where: `${v.unit.one} ${o.unit}, ${pack.tables[o.table]?.title ?? o.table}`,
344	      hit: o.targetSubject,
345	      ...(named(o.targetSubject) ? { hitName: named(o.targetSubject)! } : {}),
346	      text: entryTextOf(pack, o),
347	    }));
348	  const latest = log[0] ? { where: log[0].where, text: log[0].text } : null;
349	  // Every result this unit, in the order the dice landed on them, a
350	  // table rolled twice (an extra roll owed) shows both, oldest first,
351	  // for "this unit so far" rather than the whole run's log.
352	  const unitResults = state.outcomes
353	    .filter((o) => o.unit === state.unit)
354	    .map((o) => ({
355	      table: pack.tables[o.table]?.title ?? o.table,
356	      text: entryTextOf(pack, o),
357	      hit: o.targetSubject,
358	      ...(named(o.targetSubject) ? { hitName: named(o.targetSubject)! } : {}),
359	    }));
360	  const constraints = step ? constraintsFor(pack, state, constrainedByOf(step.step)) : [];
361	  const unitClock = clockOfUnit(state, state.unit);
362	  const clocks = [...liveClocks(state), ...(unitClock?.status === "done" ? [unitClock] : [])].map((c) => ({
363	    id: c.id,
364	    label: c.label,
365	    kind: c.kind,
366	    seconds: c.seconds,
367	    status: c.status,
368	    elapsedMs: c.status === "done" ? (c.elapsedMs ?? 0) : elapsedMs(c, now),
369	    expired: c.expired,
370	  }));
371	  const progress = progressOf(state, events, now);
372	  const score = scoreOf(pack, state, events, now);
373	  return {
374	    v: 1,
375	    at,
376	    packId: pack.id,
377	    packTitle: pack.title,
378	    runName: state.name,
379	    mode: pack.modes[state.mode]?.label ?? state.mode,
380	    modeId: state.mode,
381	    words: { run: v.run.one, unit: v.unit.one, units: v.unit.many },
382	    status: state.status === "ended" ? "ended" : "active",
383	    ending: state.ending,
384	    unit: state.unit,
385	    where: step && stepLabel ? `${step.phase.label} · ${stepLabel}` : null,
386	    step: stepLabel,
387	    stepKind: step?.step.kind ?? null,
388	    asks: {
389	      roll: step?.step.kind === "rollTable",
390	      // The same rule the table itself offers by: what is open at any time
391	      // while a step is in hand, and the between-units and ending moves at
392	      // the one moment the player is deciding whether to stop.
393	      moves:
394	        state.status === "ended"
395	          ? []
396	          : availableMoves(pack, state, step ? "anytime" : ["betweenUnits", "beforeEnding"]).map((m) => ({
397	              id: m.id,
398	              label: m.move.label,
399	            })),
400	    },
401	    phases,
402	    units,
403	    constraints,
404	    quoted,
405	    standings: standings(state).map((s) => ({
406	      name: s.contestant.name,
407	      points: s.points,
408	      place: s.place,
409	      states: s.contestant.states.map(stateLabel),
410	    })),
411	    contestants: state.contestants.length,
412	    subjects: state.subjects
413	      .filter((s) => !s.removed)
414	      .map((s) => ({
415	        id: s.id,
416	        name: subjectName(pack, s),
417	        type: s.type,
418	        states: s.states.map(stateLabel),
419	        finalized: s.finalized,
420	        hits: hitsOn(pack, state, s.id).map((h) => h.table),
421	      })),
422	    counters: Object.entries(pack.counters ?? {})
423	      .filter(([, c]) => !c.hidden)
424	      .map(([id, c]) => ({ id, label: c.label, value: state.counters[id] ?? 0 })),
425	    resources: Object.entries(pack.resources ?? {}).map(([id, r]) => ({
426	      id,
427	      label: r.label,
428	      value: state.resources[id] ?? r.initial,
429	      ...(r.max !== undefined ? { max: r.max } : {}),
430	      ...(r.display ? { display: r.display } : {}),
431	    })),
432	    clocks,
433	    progress: {
434	      unitsDone: progress.unitsDone,
435	      elapsedMs: progress.elapsedMs,
436	      timed: unitClockFor(pack, state) !== null || state.clocks.some((c) => c.id.endsWith(":unit")),
437	    },
438	    score: { label: score.label, text: formatScore(score, pack), value: score.value, better: score.better },
439	    forcedUnits: state.forcedUnits,
440	    log,
441	    unitResults,
442	    latest,
443	    ...(extra.race ? { race: extra.race } : {}),
444	  };
445	}
446	
447	/** What a snapshot from the server looks like enough to trust; the rest is defaults. */
448	export function isSnapshot(value: unknown): value is LiveSnapshot {
449	  return (
450	    typeof value === "object" &&
451	    value !== null &&
452	    (value as { v?: unknown }).v === 1 &&
453	    typeof (value as { packTitle?: unknown }).packTitle === "string"
454	  );
455	}
456	
457	/** A clock's face now, from where it stood when the snapshot was taken. */
458	export function clockNow(clock: LiveSnapshot["clocks"][number], at: string, now: number): { shown: number; fraction: number | null } {
459	  const since = clock.status === "running" ? Math.max(0, now - Date.parse(at)) : 0;
460	  const elapsed = clock.elapsedMs + since;
461	  if (clock.seconds !== null) {
462	    const left = Math.max(0, clock.seconds * 1000 - elapsed);
463	    return { shown: left, fraction: Math.max(0, Math.min(1, left / (clock.seconds * 1000))) };
464	  }
465	  return { shown: elapsed, fraction: null };
466	}
467

