1	import { readFileSync } from "node:fs";
2	import { dirname, join } from "node:path";
3	import { fileURLToPath } from "node:url";
4	import { describe, expect, it } from "vitest";
5	import { loadPackText } from "@runlog/rules-schema";
6	import { reduce } from "./reduce.ts";
7	import type { RunEvent } from "./events.ts";
8	import { clockNow, isSnapshot, raceOf, resultText, snapshotOf } from "./snapshot.ts";
9	import { subjectTitle } from "./eligibility.ts";
10	
11	const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
12	const r = loadPackText(readFileSync(join(repoRoot, "packs/demo/pack.yaml"), "utf8"), "yaml");
13	if (!r.ok) throw new Error("could not load the demo pack");
14	const kiln = r.pack;
15	
16	const events: RunEvent[] = [
17	  {
18	    t: "RunStarted",
19	    at: "2026-01-01T00:00:00Z",
20	    id: "e1",
21	    runId: "r1",
22	    packId: kiln.id,
23	    packVersion: kiln.version,
24	    mode: "standard",
25	    seed: null,
26	    players: 1,
27	  } as unknown as RunEvent,
28	  { t: "UnitEntered", at: "2026-01-01T00:00:01Z", id: "e2" } as unknown as RunEvent,
29	];
30	
31	describe("a live snapshot", () => {
32	  it("names what the outside may ask for: the moves offered now, and whether a table waits", () => {
33	    const state = reduce(kiln, events);
34	    const snap = snapshotOf(kiln, state, events, "2026-01-01T00:00:05Z");
35	    // The unit opens on a step a person does by hand, so there is nothing to roll.
36	    expect(snap.stepKind).toBe("manual");
37	    expect(snap.asks?.roll).toBe(false);
38	    // Moves are what the run would offer right now, by id and label, never every move the pack declares.
39	    const offered = snap.asks?.moves ?? [];
40	    expect(offered.every((m) => typeof m.id === "string" && typeof m.label === "string")).toBe(true);
41	    // Salvage is offered only when the player is deciding whether to stop, so not here.
42	    expect(Object.keys(kiln.moves ?? {})).toContain("salvage");
43	    expect(offered.some((m) => m.id === "salvage")).toBe(false);
44	  });
45	
46	  it("says a roll may be asked for once the flow reaches a table", () => {
47	    // Past the opening manual step and into the second unit, where the Kiln Check is no longer skipped.
48	    const toTable: RunEvent[] = [
49	      ...events,
50	      { t: "StepCompleted", at: "2026-01-01T00:00:02Z", id: "e3", phase: "enter", step: 0 } as unknown as RunEvent,
51	      { t: "UnitFinalized", at: "2026-01-01T00:00:03Z", id: "e4" } as unknown as RunEvent,
52	      { t: "UnitEntered", at: "2026-01-01T00:00:04Z", id: "e5" } as unknown as RunEvent,
53	      { t: "StepCompleted", at: "2026-01-01T00:00:05Z", id: "e6", phase: "enter", step: 0 } as unknown as RunEvent,
54	    ];
55	    const snap = snapshotOf(kiln, reduce(kiln, toTable), toTable, "2026-01-01T00:00:06Z");
56	    expect(snap.stepKind).toBe("rollTable");
57	    expect(snap.asks?.roll).toBe(true);
58	  });
59	
60	  it("carries the state in labels and numbers, and the log's words where the license allows", () => {
61	    const state = reduce(kiln, events);
62	    const snap = snapshotOf(kiln, state, events, "2026-01-01T00:00:05Z");
63	    expect(snap.v).toBe(1);
64	    expect(snap.packTitle).toBe(kiln.title);
65	    expect(snap.unit).toBe(1);
66	    expect(snap.words.unit).toBe(kiln.vocabulary.unit.one);
67	    expect(snap.quoted).toBe(kiln.license.redistributable !== false);
68	    expect(snap.where).toBeTruthy();
69	    expect(snap.step).toBeTruthy();
70	    expect(snap.where).toContain(snap.step!);
71	    // The unit's phases, as the player's own screen lists them: one current, the rest to come or done.
72	    expect(snap.phases.length).toBeGreaterThan(0);
73	    expect(snap.phases.filter((p) => p.state === "current")).toHaveLength(1);
74	    expect(snap.phases.every((p) => ["done", "current", "skipped", "todo"].includes(p.state))).toBe(true);
75	    // What a phase produced this unit sits under it: the declared type under the phase that declares.
76	    expect(snap.phases.every((p) => p.results === undefined)).toBe(true);
77	    const declaredEvents = [
78	      ...events,
79	      { t: "SubjectDeclared", at: "2026-01-01T00:00:02Z", id: "e3", subjectType: "A wide bowl" } as unknown as RunEvent,
